import datasets
import numpy as np
from scipy.optimize import curve_fit

ds = datasets.load_from_disk('/app/data')

# Try: brier_score = a * flops^b (through origin)  
def power_law2(x, a, b):
    return a * np.power(x, b)

# Try: brier_score = a + b * log(flops)
def log_model(x, a, b):
    return a + b * np.log(x)

# Try: brier_score = a + b / log(flops)
def inv_log(x, a, b):
    return a + b / np.log(x)

for group in sorted(set(ds['group'])):
    points = [(row['flops'], row['brier_score']) for row in ds if row['group'] == group]
    flops_vals = np.array([p[0] for p in points])
    brier_vals = np.array([p[1] for p in points])

    # log model
    try:
        popt, _ = curve_fit(log_model, flops_vals, brier_vals, p0=[-0.5, -0.05], maxfev=5000)
        pred = log_model(flops_vals, *popt)
        mse = np.mean((pred - brier_vals)**2)
        print(f'{group[:20]:20s}: log_model mse={mse:.6f}, a={popt[0]:.4f}, b={popt[1]:.4f}')
    except:
        print(f'{group[:20]:20s}: log_model failed')
"

